create or replace function public.admin_hot_seat_poll_upsert(p_title text,p_question text,p_options jsonb,p_enabled boolean default true,p_ends_at timestamptz default null) returns public.hot_seat_break_polls language plpgsql security definer set search_path=public,private as $$
declare r public.hot_seat_break_polls;
begin if not private.is_admin(auth.uid()) then raise exception 'Admin access required'; end if; if jsonb_array_length(p_options)<2 or jsonb_array_length(p_options)>6 then raise exception 'Poll needs 2-6 options'; end if; insert into public.hot_seat_break_polls(title,question,options,enabled,ends_at,created_by) values(trim(p_title),trim(p_question),p_options,p_enabled,p_ends_at,auth.uid()) returning * into r; return r; end $$;
create or replace function public.vote_hot_seat_break_poll(p_poll_id uuid,p_option_index integer) returns jsonb language plpgsql security definer set search_path=public,private as $$
declare uid uuid:=auth.uid(); r public.hot_seat_break_polls; c bigint;
begin if uid is null then raise exception 'Authentication required'; end if; select * into r from public.hot_seat_break_polls where id=p_poll_id and enabled=true; if r.id is null then raise exception 'Poll unavailable'; end if; if r.ends_at is not null and r.ends_at<=now() then raise exception 'Poll closed'; end if; if p_option_index<0 or p_option_index>=jsonb_array_length(r.options) then raise exception 'Invalid option'; end if; insert into public.hot_seat_break_poll_votes(poll_id,user_id,option_index) values(p_poll_id,uid,p_option_index) on conflict(poll_id,user_id) do update set option_index=excluded.option_index,created_at=now(); select count(*) into c from public.hot_seat_break_poll_votes where poll_id=p_poll_id and option_index=p_option_index; return jsonb_build_object('poll_id',p_poll_id,'option_index',p_option_index,'votes',c); end $$;
revoke all on function public.admin_hot_seat_poll_upsert(text,text,jsonb,boolean,timestamptz) from public,anon; grant execute on function public.admin_hot_seat_poll_upsert(text,text,jsonb,boolean,timestamptz) to authenticated;
revoke all on function public.vote_hot_seat_break_poll(uuid,integer) from public,anon; grant execute on function public.vote_hot_seat_break_poll(uuid,integer) to authenticated;